<?php require __DIR__.'/boot.php';
use Illuminate\Support\Facades\{DB, Schema};
config(['database.connections.mem' => ['driver'=>'sqlite','database'=>':memory:','prefix'=>'','foreign_key_constraints'=>true]]); config(['database.default'=>'mem']);
class Post extends Illuminate\Database\Eloquent\Model { protected $guarded = []; protected $casts = ['meta'=>'array','published'=>'boolean','at'=>'datetime']; public function comments() { return $this->hasMany(Comment::class); } }
class Comment extends Illuminate\Database\Eloquent\Model { protected $guarded = []; public function post() { return $this->belongsTo(Post::class); } }
section('schema', function () { Schema::create('posts', function ($t) { $t->id(); $t->string('title')->unique(); $t->json('meta')->nullable(); $t->boolean('published')->default(false); $t->dateTime('at')->nullable(); $t->timestamps(); }); Schema::create('comments', function ($t) { $t->id(); $t->foreignId('post_id')->constrained()->cascadeOnDelete(); $t->text('body'); $t->timestamps(); }); return Schema::getColumnListing('posts'); });
section('eloquent', function () { \Carbon\Carbon::setTestNow('2025-01-01 00:00:00'); $p = Post::create(['title'=>'Hello','meta'=>['a'=>1],'published'=>1,'at'=>'2024-05-05 10:00']); $p->comments()->createMany([['body'=>'c1'],['body'=>'c2']]); Post::create(['title'=>'Second']); return ['all'=>Post::with('comments')->orderBy('id')->get()->toArray(), 'count'=>Comment::count(), 'agg'=>DB::table('comments')->selectRaw('post_id, count(*) c')->groupBy('post_id')->get(), 'paginate'=>Post::paginate(1)->toArray(), 'where'=>Post::where('meta->a', 1)->pluck('title'), 'tx'=>DB::transaction(fn() => Post::whereKey(2)->update(['title'=>'Upd'])), 'raw'=>DB::select('select sqlite_version() is not null as v, 1.5 as f, null as n, x\'41\' as b')]; });
section('unique-violation', function () { try { Post::create(['title'=>'Hello']); } catch (Illuminate\Database\UniqueConstraintViolationException $e) { return get_class($e); } });
